    $stmt$COMMENT ON COLUMN sys_user.avatar IS 'Relative avatar path (/profile/avatar/...); empty means default avatar';$stmt$,
    $stmt$comment on table sys_engine is 'Engine registry: admin proxy forwards to the default engine; health probe uses base_url';$stmt$,
    $stmt$comment on column sys_engine.engine_type is 'Engine type (currently rust-gisserver; extensible)';$stmt$,
    $stmt$comment on column sys_engine.is_default is 'Default engine: admin proxy /map/* forward target; falls back to manager.xml mapsvc when unset';$stmt$,
    $stmt$COMMENT ON TABLE sys_service_engine IS 'Service-engine ownership: unregistered services use the default engine';$stmt$,
    $stmt$COMMENT ON COLUMN sys_service_engine.kind IS 'Service Type (cog/vector/pmtiles/mbtiles/postgis/3dtiles )';$stmt$,
    $stmt$COMMENT ON COLUMN sys_service_engine.name IS 'Service Name';$stmt$,
    $stmt$COMMENT ON COLUMN sys_service_engine.engine_id IS 'Owning engine ID (sys_engine.engine_id )';$stmt$,
    $stmt$comment on table sys_engine_event is 'Engine event log: produced by background polling (default 30s); records engine/service state changes';$stmt$,
    $stmt$comment on table sys_service_meta is 'Service metadata: two-level grouping (namespace); empty service_group means root';$stmt$,
    $stmt$comment on column sys_service_meta.service_group is 'Group Path" Level 1/ Level 2", at most two levels; empty string = root';$stmt$,
    $stmt$comment on table  sys_workspace           is 'Workspace: namespace container for map services; stores and published services belong to it';$stmt$,
    $stmt$comment on column sys_workspace.name      is 'Workspace name (URL/tree id, unique within ws)';$stmt$,
    $stmt$comment on column sys_workspace.engine_id is 'Bound engine ID (sys_engine.engine_id; empty = default engine)';$stmt$,
    $stmt$comment on column sys_workspace.data_root is 'Data file root path (use / separators, trailing / required)';$stmt$,
    $stmt$comment on column sys_workspace.del_flag  is '0 normal / 1 deleted (soft delete flag only)';$stmt$,
    $stmt$comment on table  sys_store            is 'Data store: pointer to a file directory or PostGIS connection; read-only scan at discovery, no data persisted';$stmt$,
    $stmt$comment on column sys_store.store_type is 'cog_dir|geojson_dir|shapefile_dir|pmtiles_dir|mbtiles_dir|3dtiles_dir|postgis';$stmt$,
    $stmt$comment on column sys_store.base_path  is 'Directory of file-based stores (inside map-api server.data_root; path guard enforced server-side)';$stmt$,
    $stmt$comment on column sys_store.pg_dsn     is 'PostGIS connection string: stored verbatim on the server and used only to forward to map-api; passwords are always masked in responses';$stmt$,
    $stmt$comment on table  sys_resource             is 'Data layer (Resource): discovered by directory scan / geometry_columns; metadata only';$stmt$,
    $stmt$comment on column sys_resource.data_type   is 'cog|geojson|pmtiles|pmtiles_mvt|mbtiles|mbtiles_mvt|3dtiles|postgis_table|shapefile';$stmt$,
    $stmt$comment on column sys_resource.source      is 'Data entity location: absolute file path or schema.table';$stmt$,
    $stmt$comment on column sys_resource.bbox        is 'Extent discovered read-only [minx,miny,maxx,maxy] (WGS84 or source CRS)';$stmt$,
    $stmt$comment on column sys_resource.publishable is '0 = current engine cannot publish (e.g. shapefile: no reader, planned support)';$stmt$,
    $stmt$comment on column sys_resource.reason      is 'Human-readable reason for not-publishable / probe downgrade';$stmt$,
    $stmt$comment on column sys_resource.meta        is 'Verbatim snapshot of discovery results: PostGIS geometry_column/srid, archive zoom range, 3D Tiles entry, etc., source is rebuilt from it at publish time';$stmt$,
    $stmt$comment on column sys_resource.crs_suspicious is 'Suspicious CRS: declared CRS does not match the discovered bbox; confirm manually before publishing';$stmt$,
    $stmt$comment on table  sys_published_layer               is 'Published service ledger: same source as rust-gisserver sys_service registry, identical four states';$stmt$,
    $stmt$comment on column sys_published_layer.layer_name    is 'rust-gisserver flat unique service name (= Layer name / TilesetService Name )';$stmt$,
    $stmt$comment on column sys_published_layer.service_types is 'Comma-separated protocols selected at publish: wms,wmts,xyz,wfs,mvt,oaf,3dtiles';$stmt$,
    $stmt$comment on column sys_published_layer.mapserver_kind is 'cog|vector|pmtiles|mbtiles|postgis|3dtiles (selects which XML document to write)';$stmt$,
    $stmt$comment on column sys_published_layer.state         is 'active|stopped|paused|deleted (rust-gisserver registry states)';$stmt$,
    $stmt$comment on column sys_published_layer.service_doc  is 'Complete service definition ( Layer JSON with custom_grids ): single source of truth in rust-gisserver backend=db mode, manager is the only writer';$stmt$,
    $stmt$comment on column sys_published_layer.grid         is 'Native grid snapshot frozen at publish time ( ArcGIS: CRS / tile size / origin / LOD ladder ), runtime still uses the cache Conf.xml';$stmt$,
    $stmt$comment on table  sys_api_key            is 'rust-gisserver access key: admin plane (admin) / client data plane (data)';$stmt$,
    $stmt$comment on column sys_api_key.purpose    is 'Purpose: admin = manager to server (X-Admin-Token); data = client data plane';$stmt$,
    $stmt$comment on column sys_api_key.status     is 'Status: 0 enabled / 1 disabled';$stmt$,
    $stmt$comment on column sys_api_key.expires_at is 'Expiry (empty = never expires); disabled or expired keys are ignored by server validation';$stmt$,
    $stmt$comment on column sys_workspace.data_root is 'Data file root path (use / separators, trailing / required)';$stmt$,
    $stmt$comment on column sys_workspace.engine_id is 'Bound engine ID (sys_engine.engine_id; empty = default engine)';$stmt$,
    $stmt$comment on table  sys_sld             is 'SLD style library: Database primary storage + dual write to map-api styles directory';$stmt$,
    $stmt$comment on column sys_sld.sld_id     is 'Auto-increment ID';$stmt$,
